UPDATE public.site_settings SET value = 'Minas Escadas' WHERE key = 'company_name';
UPDATE public.product_reviews SET reviewer_name = 'João Silva', review_text = 'Escada excelente, muito firme e fácil de guardar.', rating = 5 WHERE id IN (SELECT id FROM public.product_reviews WHERE product_id = '1fb98975-5187-4f9f-a51a-d4a4818f5561' LIMIT 1);